const nav = document.querySelector('.nav');
const menu = document.querySelector('.menu-button');
function closeMenu(returnFocus=false){nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.innerHTML=FieldGuideIcons.menu;if(returnFocus)menu.focus()}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('is-open',open);menu.innerHTML=open?FieldGuideIcons.close:FieldGuideIcons.menu});
nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true')closeMenu(true)});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.site-header'))closeMenu()});
document.querySelector('.site-header').addEventListener('focusout',e=>{if(!e.currentTarget.contains(e.relatedTarget))closeMenu()});
matchMedia('(min-width:1081px)').addEventListener('change',()=>closeMenu());
if(typeof lessons!=='undefined'){
 const list=document.getElementById('lesson-list'),content=document.getElementById('lesson-content');
 const storageKey='technical-writing-fieldguide-v1';let saved={reviewed:[],notes:{}};let storageWorks=true;
 try{const raw=JSON.parse(localStorage.getItem(storageKey)||'null');if(raw&&Array.isArray(raw.reviewed)&&raw.notes&&typeof raw.notes==='object')saved=raw;localStorage.setItem(storageKey,JSON.stringify(saved))}catch{storageWorks=false}
 function persist(){try{localStorage.setItem(storageKey,JSON.stringify(saved));return true}catch{storageWorks=false;return false}}
 function progress(){const count=lessons.filter(l=>saved.reviewed.includes(l.slug)).length;document.getElementById('progress-text').textContent=`${count} of ${lessons.length} lessons marked reviewed`;document.getElementById('progress-fill').style.width=`${count/lessons.length*100}%`}
 list.innerHTML=lessons.map((l,i)=>`<li><a href="#lesson-${l.slug}" data-slug="${l.slug}"><span>${i+1}</span><span>${l.title}</span></a></li>`).join('');
 function render(slug,scroll=false){const index=Math.max(0,lessons.findIndex(l=>l.slug===slug)),l=lessons[index],done=saved.reviewed.includes(l.slug);list.querySelectorAll('a').forEach(a=>{if(a.dataset.slug===l.slug)a.setAttribute('aria-current','step');else a.removeAttribute('aria-current')});content.innerHTML=`<div class="lesson-meta mono"><span>${l.group}</span><span>Lesson ${index+1} / ${lessons.length}</span></div><h2 id="lesson-title" tabindex="-1">${l.title}</h2><p class="lesson-intro">${l.intro}</p><div class="lesson-body">${l.body}</div><section class="practice" aria-labelledby="practice-title"><span class="label">Put it into practice</span><h3 id="practice-title">Try it with your own words.</h3><p>${l.practice}</p><label for="practice-note" class="label">Your working notes</label><textarea id="practice-note" placeholder="Draft your answer here…"></textarea><p class="practice-status" id="note-status" aria-live="polite">${storageWorks?'Notes stay in this browser.':'Browser storage is unavailable. Notes will last for this visit.'}</p><button class="answer-toggle" aria-expanded="false" aria-controls="sample-answer">Show a sample answer</button><div class="sample-answer" id="sample-answer" hidden><span class="label">One possible answer</span><p>${l.answer}</p></div></section><div class="lesson-takeaway"><span class="label">Keep this rule</span><p>${l.takeaway}</p></div><div class="lesson-footer"><button class="small-button" id="mark-reviewed" aria-pressed="${done}">${done?'Marked reviewed':'Mark as reviewed'}</button>${index<lessons.length-1?`<a class="button" href="#lesson-${lessons[index+1].slug}">Next: ${lessons[index+1].title}</a>`:'<a class="button" href="#review">Review your draft</a>'}</div>`;
 const textarea=document.getElementById('practice-note');textarea.value=typeof saved.notes[l.slug]==='string'?saved.notes[l.slug]:'';let timer;textarea.addEventListener('input',()=>{saved.notes[l.slug]=textarea.value;clearTimeout(timer);const ok=persist();const status=document.getElementById('note-status');timer=setTimeout(()=>{if(status.isConnected)status.textContent=ok?'Notes saved in this browser.':'Browser storage is unavailable. Keep a copy before leaving.'},300)});
 document.querySelector('.answer-toggle').addEventListener('click',e=>{const open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.textContent=open?'Hide sample answer':'Show a sample answer';document.getElementById('sample-answer').hidden=!open});
 document.getElementById('mark-reviewed').addEventListener('click',e=>{const wasDone=saved.reviewed.includes(l.slug);saved.reviewed=wasDone?saved.reviewed.filter(s=>s!==l.slug):[...saved.reviewed,l.slug];const ok=persist();e.currentTarget.setAttribute('aria-pressed',String(!wasDone));e.currentTarget.textContent=wasDone?'Mark as reviewed':'Marked reviewed';if(!ok)document.getElementById('note-status').textContent='Browser storage is unavailable. Review marks will last for this visit.';progress()});
 progress();if(scroll){content.scrollIntoView({block:'start'});document.getElementById('lesson-title').focus({preventScroll:true})}
 }
 function route(scroll){const slug=location.hash.replace('#lesson-','');if(location.hash.startsWith('#lesson-'))render(slug,scroll)}
 render('audience');route(false);if(location.hash.startsWith('#lesson-'))requestAnimationFrame(()=>content.scrollIntoView({block:'start',behavior:'instant'}));window.addEventListener('hashchange',()=>route(true));list.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.hash===location.hash){e.preventDefault();render(a.dataset.slug,true)}});
}
